function check(name, actual, expected, relTol) {
  const rel = Math.abs(actual - expected) / Math.abs(expected);
  const ok = rel <= relTol;
  if (!ok) failures++;
  console.log(`${ok ? "PASS" : "FAIL"} ${name}: app=${actual} model=${expected} rel=${rel.toExponential(3)} tol=${relTol}`);
